import{_ as r,o as n,c as o,a5 as a}from"./chunks/framework.Cooo9kuv.js";const c=JSON.parse('{"title":"程序使用环境及相关说明","description":"","frontmatter":{"标题":"801-拖入文件夹自动压缩为压缩包V2.0","日期":"2026-05-23T00:00:00.000Z","修改日期":"2026-05-23T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["定制类程序"],"标签":["softbangong","办公文件整理","压缩包密码管理","压缩包自动加密","批量压缩软件","文件分发助手","文件夹批量压缩","文件逐个打包","资料归档工具"]},"headers":[{"level":3,"title":"快速上手","slug":"快速上手","link":"#快速上手","children":[]},{"level":3,"title":"功能特点","slug":"功能特点","link":"#功能特点","children":[]},{"level":3,"title":"适用人群","slug":"适用人群","link":"#适用人群","children":[]},{"level":3,"title":"解决的痛点","slug":"解决的痛点","link":"#解决的痛点","children":[]},{"level":3,"title":"界面介绍","slug":"界面介绍","link":"#界面介绍","children":[]},{"level":3,"title":"主界面布局","slug":"主界面布局","link":"#主界面布局","children":[]},{"level":3,"title":"功能按钮","slug":"功能按钮","link":"#功能按钮","children":[]},{"level":3,"title":"基本操作指南","slug":"基本操作指南","link":"#基本操作指南","children":[]},{"level":3,"title":"操作1：压缩单个文件夹","slug":"操作1-压缩单个文件夹","link":"#操作1-压缩单个文件夹","children":[]},{"level":3,"title":"操作2：使用密码库文件","slug":"操作2-使用密码库文件","link":"#操作2-使用密码库文件","children":[]},{"level":3,"title":"操作3：添加额外内容到压缩包","slug":"操作3-添加额外内容到压缩包","link":"#操作3-添加额外内容到压缩包","children":[]},{"level":3,"title":"实际使用场景示例","slug":"实际使用场景示例","link":"#实际使用场景示例","children":[]},{"level":3,"title":"场景1：教师打包课程资料发给学生","slug":"场景1-教师打包课程资料发给学生","link":"#场景1-教师打包课程资料发给学生","children":[]},{"level":3,"title":"场景2：设计师给客户发送设计稿","slug":"场景2-设计师给客户发送设计稿","link":"#场景2-设计师给客户发送设计稿","children":[]},{"level":3,"title":"场景3：行政人员归档工作资料","slug":"场景3-行政人员归档工作资料","link":"#场景3-行政人员归档工作资料","children":[]},{"level":3,"title":"数据存储位置","slug":"数据存储位置","link":"#数据存储位置","children":[]},{"level":3,"title":"文件说明","slug":"文件说明","link":"#文件说明","children":[]},{"level":3,"title":"注意事项","slug":"注意事项","link":"#注意事项","children":[]},{"level":3,"title":"常见问题解答","slug":"常见问题解答","link":"#常见问题解答","children":[]},{"level":3,"title":"问题1：点击开始压缩按钮后没有反应怎么办","slug":"问题1-点击开始压缩按钮后没有反应怎么办","link":"#问题1-点击开始压缩按钮后没有反应怎么办","children":[]},{"level":3,"title":"问题2：压缩包解压时提示密码错误","slug":"问题2-压缩包解压时提示密码错误","link":"#问题2-压缩包解压时提示密码错误","children":[]},{"level":3,"title":"问题3：密码库文件里的密码不够用怎么办","slug":"问题3-密码库文件里的密码不够用怎么办","link":"#问题3-密码库文件里的密码不够用怎么办","children":[]},{"level":3,"title":"问题4：额外添加的URL或文本文件能在原文件夹里看到吗","slug":"问题4-额外添加的url或文本文件能在原文件夹里看到吗","link":"#问题4-额外添加的url或文本文件能在原文件夹里看到吗","children":[]},{"level":3,"title":"问题5：可以同时压缩多个文件夹吗","slug":"问题5-可以同时压缩多个文件夹吗","link":"#问题5-可以同时压缩多个文件夹吗","children":[]},{"level":3,"title":"问题6：压缩格式选错了能重新压缩吗","slug":"问题6-压缩格式选错了能重新压缩吗","link":"#问题6-压缩格式选错了能重新压缩吗","children":[]},{"level":3,"title":"系统要求","slug":"系统要求","link":"#系统要求","children":[]}],"relativePath":"md/定制类程序/801-拖入文件夹自动压缩为压缩包V2.0.md","filePath":"md/定制类程序/801-拖入文件夹自动压缩为压缩包V2.0.md"}'),s={name:"md/定制类程序/801-拖入文件夹自动压缩为压缩包V2.0.md"};function e(l,t,g,p,i,h){return n(),o("div",null,[...t[0]||(t[0]=[a('<p>这个工具可以把你拖进来的文件夹里的每个文件和子文件夹分别压缩成独立的压缩包，支持7z、zip、rar三种格式，还能给压缩包设置密码、添加URL快捷方式或文本文件，或文件或文件夹一起打包。</p><p>你只需要把文件夹拖进窗口，点一下压缩按钮，程序就会自动帮你把所有文件一个个打包好，还会自动生成密码记录文件，省去你手动逐个压缩的麻烦。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/05/image-14.png" alt=""></p><h3 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h3><p>只看这里就够了，三步走完。</p><p><strong>第一步</strong>：把要压缩的文件夹<strong>拖进来</strong>到拖拽列表区域，或者点击<strong>浏览按钮</strong>选择文件夹。</p><p><strong>第二步</strong>：选择压缩格式和密码方式，然后点击<strong>开始压缩按钮</strong>，程序会自动完成所有操作。</p><p><strong>第三步</strong>：去原文件夹所在的目录，找到以<strong>原文件夹名-压缩包及解压密码</strong>命名的文件夹，里面就是压缩好的文件。</p><h3 id="功能特点" tabindex="-1">功能特点 <a class="header-anchor" href="#功能特点" aria-label="Permalink to &quot;功能特点&quot;">​</a></h3><p><strong>逐个独立压缩</strong>：文件夹根目录下的每个文件和子文件夹都会被分别压缩成独立的压缩包，不会把所有文件打包成一个。</p><p><strong>三种压缩格式</strong>：支持7z、zip、rar三种主流压缩格式，你可以根据需要自由选择。</p><p><strong>灵活密码管理</strong>：支持无密码、统一密码、密码库文件三种方式。密码库文件每行一个密码，程序会按顺序依次分配给每个压缩包，用完后自动更新密码库。</p><p><strong>额外内容打包</strong>：可以在压缩时额外添加URL快捷方式、文本文件、其他文件或文件夹，这些内容会直接打包进每个压缩包内，不会在原文件夹中创建实体文件。</p><p><strong>自动密码记录</strong>：压缩完成后会自动记录每个压缩包对应的解压密码，方便你日后查找。</p><p><strong>批量处理支持</strong>：支持同时添加多个文件夹进行压缩，拖拽列表和批量列表中的文件夹都会被处理。</p><h3 id="适用人群" tabindex="-1">适用人群 <a class="header-anchor" href="#适用人群" aria-label="Permalink to &quot;适用人群&quot;">​</a></h3><p>经常需要打包分享资料的<strong>教师和学生</strong>。</p><p>需要定期归档工作文件的<strong>行政财务人员</strong>。</p><p>手头有大量项目文件需要分发的<strong>程序员和设计师</strong>。</p><p>需要给客户发送独立文件包的<strong>自由职业者</strong>。</p><p>经常整理下载资料、照片视频的<strong>家庭用户</strong>。</p><h3 id="解决的痛点" tabindex="-1">解决的痛点 <a class="header-anchor" href="#解决的痛点" aria-label="Permalink to &quot;解决的痛点&quot;">​</a></h3><p>以前你可能是这样做的，又慢又麻烦：</p><p><strong>痛点1</strong>：一个一个右键选择压缩，100个文件要点100次右键再选压缩，手指都点酸了。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/05/image-15.png" alt=""></p><p><strong>用这个工具后</strong>：拖进文件夹点一下按钮，全部自动搞定，喝口水的功夫就处理完了。</p><p><strong>痛点2</strong>：给每个压缩包设置不同密码太麻烦，要么全部用同一个密码不安全，要么记不住哪个文件用的哪个密码。</p><p><strong>用这个工具后</strong>：密码库文件一行一个密码，程序自动按顺序分配，还自动生成密码记录文件，再也不用操心密码对应关系。</p><p><strong>痛点3</strong>：想给每个压缩包都附带一个说明文件或网址链接，得先手动创建文件再打包，步骤繁琐。</p><p><strong>用这个工具后</strong>：直接在界面添加URL或文本内容，程序会自动创建并打包进每个压缩包，不污染原文件夹。</p><h3 id="界面介绍" tabindex="-1">界面介绍 <a class="header-anchor" href="#界面介绍" aria-label="Permalink to &quot;界面介绍&quot;">​</a></h3><h3 id="主界面布局" tabindex="-1">主界面布局 <a class="header-anchor" href="#主界面布局" aria-label="Permalink to &quot;主界面布局&quot;">​</a></h3><p><strong>拖拽列表区域</strong>：位于界面上方，你可以把要压缩的文件夹直接拖拽到这个区域，文件夹路径会自动添加到列表中。每个添加的文件夹右侧都有一个 <strong>X 按钮</strong>，点击可以移除该项。</p><p><strong>批量添加区域</strong>：位于界面中部，你可以通过浏览按钮选择文件夹添加到这个列表。拖拽列表和批量列表中的文件夹都会被一起压缩处理。</p><p><strong>额外添加区域</strong>：用于添加要打包进压缩包的其他内容，支持URL链接、文本内容、文件和文件夹四种类型。</p><p><strong>密码设置区域</strong>：提供三种密码方式选择，分别是无密码、密码库文件、统一密码。选择密码库文件方式时需要点击浏览按钮选择txt文件。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/05/image-16.png" alt=""></p><p><strong>格式和保存设置区域</strong>：可以选择压缩格式（7z、zip、rar）和保存位置（原目录或指定目录）。</p><h3 id="功能按钮" tabindex="-1">功能按钮 <a class="header-anchor" href="#功能按钮" aria-label="Permalink to &quot;功能按钮&quot;">​</a></h3><p><strong>浏览按钮</strong>：用于选择文件夹或密码库文件，点击后弹出文件选择对话框。</p><p><strong>开始压缩按钮</strong>：点击后开始执行压缩任务，压缩过程中按钮会变灰禁用，完成后自动恢复。</p><p><strong>清空列表按钮</strong>：点击后清空拖拽列表中的所有文件夹项。</p><h3 id="基本操作指南" tabindex="-1">基本操作指南 <a class="header-anchor" href="#基本操作指南" aria-label="Permalink to &quot;基本操作指南&quot;">​</a></h3><h3 id="操作1-压缩单个文件夹" tabindex="-1">操作1：压缩单个文件夹 <a class="header-anchor" href="#操作1-压缩单个文件夹" aria-label="Permalink to &quot;操作1：压缩单个文件夹&quot;">​</a></h3><p><strong>第一步</strong>，把要压缩的文件夹拖拽到拖拽列表区域，或者点击浏览按钮选择文件夹添加到批量列表。</p><p><strong>第二步</strong>，在格式选择下拉菜单中选择你想要的压缩格式，可选7z、zip或rar。</p><p><strong>第三步</strong>，选择密码方式。如果不需要密码就选无密码，如果要统一密码就选统一密码并在输入框中输入密码，如果要每个文件不同密码就选密码库文件并选择你的txt密码文件。</p><p><strong>第四步</strong>，点击开始压缩按钮，等待日志区域显示压缩完成。</p><hr><p>示例：你想把 <strong>E:\\工作资料</strong> 文件夹里的每个文件分别压缩成7z格式，并且都加上密码 <strong>123456</strong>。</p><p>你把 <strong>E:\\工作资料</strong> 拖进拖拽列表区域，格式选择 <strong>7z</strong>，密码方式选择 <strong>统一密码</strong>，在密码输入框输入 <strong>123456</strong>，然后点击开始压缩按钮。</p><p>压缩完成后，在 *<em>E:*</em> 目录下会出现一个名为 <strong>工作资料-压缩包及解压密码</strong> 的文件夹，里面每个文件都有自己独立的子文件夹，子文件夹里就是对应的7z压缩包，同时还有一个密码记录文件。</p><hr><h3 id="操作2-使用密码库文件" tabindex="-1">操作2：使用密码库文件 <a class="header-anchor" href="#操作2-使用密码库文件" aria-label="Permalink to &quot;操作2：使用密码库文件&quot;">​</a></h3><p><strong>第一步</strong>，准备一个txt格式的密码库文件，每行写一个密码，例如第一行写 <strong>abc123</strong>，第二行写 <strong>def456</strong>，第三行写 <strong>ghi789</strong>。</p><p><strong>第二步</strong>，把要压缩的文件夹添加到列表中。</p><p><strong>第三步</strong>，密码方式选择 <strong>密码库文件</strong>，点击浏览按钮选择你准备好的txt密码文件。</p><p><strong>第四步</strong>，点击开始压缩按钮，程序会按顺序把密码库里的密码依次分配给每个压缩包。</p><hr><p>示例：你的文件夹里有5个文件，密码库文件里有8个密码。</p><p>程序会把密码库的前5个密码分别给5个压缩包使用，压缩完成后密码库文件会自动更新，只剩下剩余的3个密码，下次使用接着从剩下的密码开始分配。</p><p>压缩完成后会生成一个密码记录文件，里面清楚记录了每个压缩包用的是哪个密码，你不用担心忘记对应关系。</p><hr><h3 id="操作3-添加额外内容到压缩包" tabindex="-1">操作3：添加额外内容到压缩包 <a class="header-anchor" href="#操作3-添加额外内容到压缩包" aria-label="Permalink to &quot;操作3：添加额外内容到压缩包&quot;">​</a></h3><p><strong>第一步</strong>，在额外添加区域选择要添加的类型，可以是URL链接、文本内容、文件或文件夹。</p><p><strong>第二步</strong>，输入URL地址或文本内容，或者浏览选择要添加的文件或文件夹。你也可以自定义文件名，不填的话程序会自动生成。</p><p><strong>第三步</strong>，点击添加按钮，额外项目会显示在列表中。</p><p><strong>第四步</strong>，正常执行压缩操作，这些额外内容会被打包进每个压缩包内。</p><hr><p>示例：你想给每个压缩包都附带一个公司官网链接和一段使用说明。</p><p>你在额外添加区域选择 <strong>URL</strong> 类型，输入 <strong><a href="https://www.example.com/" target="_blank" rel="noreferrer">https://www.example.com</a></strong>，自定义文件名填 <strong>公司官网</strong>，点击添加。然后选择 <strong>文本</strong> 类型，输入使用说明内容，自定义文件名填 <strong>使用说明</strong>，点击添加。</p><p>压缩完成后，每个压缩包解压出来都会包含一个 <strong>公司官网.url</strong> 快捷方式文件和一个 <strong>使用说明.txt</strong> 文本文件，不需要你手动去每个文件夹里创建。</p><hr><h3 id="实际使用场景示例" tabindex="-1">实际使用场景示例 <a class="header-anchor" href="#实际使用场景示例" aria-label="Permalink to &quot;实际使用场景示例&quot;">​</a></h3><h3 id="场景1-教师打包课程资料发给学生" tabindex="-1">场景1：教师打包课程资料发给学生 <a class="header-anchor" href="#场景1-教师打包课程资料发给学生" aria-label="Permalink to &quot;场景1：教师打包课程资料发给学生&quot;">​</a></h3><p>场景描述：你是老师，期末了需要把一学期的课件、作业、试卷等20多个文件分别压缩成独立的压缩包发给学生，每个文件都要设置不同的密码保证安全性。</p><p><strong>第一步</strong>，在桌面新建一个txt文件，里面写20行不同的密码，每行一个。</p><p><strong>第二步</strong>，打开程序，把存放课程资料的文件夹拖进拖拽列表区域。</p><p><strong>第三步</strong>，格式选择 <strong>7z</strong>，密码方式选择 <strong>密码库文件</strong>，浏览选择你刚才创建的密码txt文件。</p><p><strong>第四步</strong>，点击开始压缩按钮，等待压缩完成。</p><p>预期结果：在课程资料文件夹所在目录会出现一个 <strong>课程资料-压缩包及解压密码</strong> 的文件夹，里面有20个子文件夹，每个子文件夹里有一个压缩包和对应的密码，同时还有一个密码记录文件汇总了所有压缩包和密码的对应关系，你直接把整个文件夹发给学生就行。</p><hr><h3 id="场景2-设计师给客户发送设计稿" tabindex="-1">场景2：设计师给客户发送设计稿 <a class="header-anchor" href="#场景2-设计师给客户发送设计稿" aria-label="Permalink to &quot;场景2：设计师给客户发送设计稿&quot;">​</a></h3><p>场景描述：你是设计师，给客户做了10张设计图，需要把每张图单独压缩并附带一个公司官网链接和使用说明文档一起发给客户。</p><p><strong>第一步</strong>，把存放设计图的文件夹拖进拖拽列表区域。</p><p><strong>第二步</strong>，格式选择 <strong>zip</strong>（兼容性最好，客户不需要额外安装解压软件），密码方式选择 <strong>统一密码</strong>，输入密码 <strong>design2024</strong>。</p><p><strong>第三步</strong>，在额外添加区域添加URL类型，输入公司官网地址，自定义文件名填 <strong>公司官网</strong>。再添加文本类型，输入使用说明内容，自定义文件名填 <strong>使用须知</strong>。</p><p><strong>第四步</strong>，点击开始压缩按钮。</p><p>预期结果：生成的10个zip压缩包每个都包含了设计图文件、公司官网快捷方式和使用须知文本文件，客户解压后能直接看到所有相关内容，不需要你额外发送说明文件。</p><hr><h3 id="场景3-行政人员归档工作资料" tabindex="-1">场景3：行政人员归档工作资料 <a class="header-anchor" href="#场景3-行政人员归档工作资料" aria-label="Permalink to &quot;场景3：行政人员归档工作资料&quot;">​</a></h3><p>场景描述：你是行政人员，每个月都要把各部门提交的工作报告、发票、凭证等文件归档，需要压缩保存并记录每个文件的解压密码，方便日后查找。</p><p><strong>第一步</strong>，把当月的工作资料文件夹拖进拖拽列表区域。</p><p><strong>第二步</strong>，格式选择 <strong>rar</strong>，密码方式选择 <strong>密码库文件</strong>，选择你维护的密码库文件。</p><p><strong>第三步</strong>，保存位置选择 <strong>指定目录</strong>，浏览选择你专门用来存放归档压缩包的硬盘分区。</p><p><strong>第四步</strong>，点击开始压缩按钮。</p><p>预期结果：所有文件被分别压缩后保存到你指定的目录，每个压缩包在自己的子文件夹里，密码记录文件汇总了所有密码，密码库文件自动扣除了已使用的密码。你只需要把这个月的归档文件夹重命名后保存就行，下次归档接着用剩余的密码。</p><hr><h3 id="数据存储位置" tabindex="-1">数据存储位置 <a class="header-anchor" href="#数据存储位置" aria-label="Permalink to &quot;数据存储位置&quot;">​</a></h3><p><strong>压缩包及密码文件夹</strong>：默认保存在原文件夹所在的目录，文件夹名称为 <strong>原文件夹名-压缩包及解压密码</strong>。如果选择了指定目录保存，则保存在你选择的目标目录。</p><p><strong>单个压缩包</strong>：每个压缩包都存放在 <strong>压缩包及密码文件夹</strong> 内以原文件名命名的子文件夹中。</p><p><strong>密码记录文件</strong>：保存在 <strong>压缩包及密码文件夹</strong> 内，文件名为 <strong>原文件夹名-压缩包解压密码.txt</strong>。</p><p><strong>程序配置文件</strong>：保存在程序同级目录下的 <strong>app_config.json</strong> 文件中，记录你的密码库路径等设置。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/05/image-17.png" alt=""></p><h3 id="文件说明" tabindex="-1">文件说明 <a class="header-anchor" href="#文件说明" aria-label="Permalink to &quot;文件说明&quot;">​</a></h3><p>下载后你看到的每个文件是干什么的：</p><p>主程序文件，双击运行打开图形界面。不能删。</p><p><strong>app_config.json</strong>：程序自动生成的配置文件，保存你的设置信息，如密码库文件路径。不能删，删了每次打开都要重新设置。</p><p><strong>压缩包及解压密码文件夹</strong>：压缩完成后自动生成的输出文件夹，里面是压缩结果。可以删，删了重新压缩就行。</p><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><p>重要提示：处理前请务必备份重要数据，误操作可能导致文件丢失且不可恢复。</p><p>压缩前确认目标文件夹有<strong>足够空间</strong>存放所有压缩包，特别是文件夹内有大文件时。</p><p>** C:\\apitool文件夹必须在使用程序前进行设置**</p><p>密码库文件必须是<strong>txt格式</strong>，每行一个密码，空行会被自动忽略。</p><p>压缩过程中<strong>不要关闭程序窗口</strong>，等待日志区域显示压缩完成提示。</p><p>首次使用建议<strong>先用少量文件测试</strong>，确认压缩效果和格式符合预期后再批量处理。</p><p>如果程序界面无响应，耐心等待片刻，大文件压缩可能需要较长时间，后台仍在工作中。</p><p>压缩完成后记得检查密码记录文件，确认每个压缩包都有对应的密码记录。</p><h3 id="常见问题解答" tabindex="-1">常见问题解答 <a class="header-anchor" href="#常见问题解答" aria-label="Permalink to &quot;常见问题解答&quot;">​</a></h3><h3 id="问题1-点击开始压缩按钮后没有反应怎么办" tabindex="-1">问题1：点击开始压缩按钮后没有反应怎么办 <a class="header-anchor" href="#问题1-点击开始压缩按钮后没有反应怎么办" aria-label="Permalink to &quot;问题1：点击开始压缩按钮后没有反应怎么办&quot;">​</a></h3><p>答案：先检查拖拽列表和批量列表是否为空，两个列表都没有文件夹的话程序不会执行压缩。然后查看日志区域是否有错误提示，常见错误是压缩软件路径不正确或文件夹路径无效。如果日志显示压缩软件未找到，<strong>说明没有将apitool文件夹复制到C盘</strong></p><hr><h3 id="问题2-压缩包解压时提示密码错误" tabindex="-1">问题2：压缩包解压时提示密码错误 <a class="header-anchor" href="#问题2-压缩包解压时提示密码错误" aria-label="Permalink to &quot;问题2：压缩包解压时提示密码错误&quot;">​</a></h3><p>答案：打开压缩包所在文件夹里的密码记录文件 <strong>原文件夹名-压缩包解压密码.txt</strong>，找到对应压缩包的密码。密码记录文件的格式是压缩包名称和密码交替排列，每个压缩包占两行。如果密码记录文件里没有对应密码，说明压缩时使用的是无密码方式。</p><hr><h3 id="问题3-密码库文件里的密码不够用怎么办" tabindex="-1">问题3：密码库文件里的密码不够用怎么办 <a class="header-anchor" href="#问题3-密码库文件里的密码不够用怎么办" aria-label="Permalink to &quot;问题3：密码库文件里的密码不够用怎么办&quot;">​</a></h3><p>答案：程序会按顺序使用密码库里的密码，用完后剩余的压缩包会使用无密码方式压缩。你可以在密码库里多准备一些密码，确保数量大于等于文件夹里的文件数量（一行一个密码没有限制）。压缩完成后密码库文件会自动更新，只保留未使用的密码，你可以随时往密码库里添加新密码。</p><hr><h3 id="问题4-额外添加的url或文本文件能在原文件夹里看到吗" tabindex="-1">问题4：额外添加的URL或文本文件能在原文件夹里看到吗 <a class="header-anchor" href="#问题4-额外添加的url或文本文件能在原文件夹里看到吗" aria-label="Permalink to &quot;问题4：额外添加的URL或文本文件能在原文件夹里看到吗&quot;">​</a></h3><p>答案：不能。额外添加的URL快捷方式和文本文件是在临时目录创建的，直接打包进压缩包内，不会在你的原文件夹中留下任何痕迹。压缩完成后临时文件会被自动清理，原文件夹保持原样不受影响。</p><hr><h3 id="问题5-可以同时压缩多个文件夹吗" tabindex="-1">问题5：可以同时压缩多个文件夹吗 <a class="header-anchor" href="#问题5-可以同时压缩多个文件夹吗" aria-label="Permalink to &quot;问题5：可以同时压缩多个文件夹吗&quot;">​</a></h3><p>答案：可以。你可以往拖拽列表区域拖拽多个文件夹，也可以通过浏览按钮往批量列表添加多个文件夹。两个列表中的文件夹都会被处理，每个文件夹都会生成独立的压缩包及密码文件夹。</p><hr><h3 id="问题6-压缩格式选错了能重新压缩吗" tabindex="-1">问题6：压缩格式选错了能重新压缩吗 <a class="header-anchor" href="#问题6-压缩格式选错了能重新压缩吗" aria-label="Permalink to &quot;问题6：压缩格式选错了能重新压缩吗&quot;">​</a></h3><p>答案：可以。压缩完成后原文件夹不会被修改或删除，你可以重新选择格式再次压缩。每次压缩都会生成新的输出文件夹，不会覆盖之前的结果。建议确认格式无误后再压缩，避免重复操作浪费时间。</p><h3 id="系统要求" tabindex="-1">系统要求 <a class="header-anchor" href="#系统要求" aria-label="Permalink to &quot;系统要求&quot;">​</a></h3><p>Windows 7 及以上 64 位操作系统。</p><p>使用前先将apitool文件夹复制或移动到C盘，结果为：<strong>C:\\apitool</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/05/image-18.png" alt=""></p><h1 id="程序使用环境及相关说明" tabindex="-1">程序使用环境及相关说明 <a class="header-anchor" href="#程序使用环境及相关说明" aria-label="Permalink to &quot;程序使用环境及相关说明&quot;">​</a></h1><p><strong>1、适用的系统环境说明</strong>：</p><p>win7及以上64位windows操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：</p><p>①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p>**3、程序如何安装：**不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p><h1 id="程序使用说明" tabindex="-1">程序使用说明 <a class="header-anchor" href="#程序使用说明" aria-label="Permalink to &quot;程序使用说明&quot;">​</a></h1><p><strong>解压后直接使用即可，不需要安装，程序可以放在任意位置</strong></p><h1 id="程序使用环境及相关说明-1" tabindex="-1">程序使用环境及相关说明 <a class="header-anchor" href="#程序使用环境及相关说明-1" aria-label="Permalink to &quot;程序使用环境及相关说明&quot;">​</a></h1><p><strong>1、适用的系统环境说明</strong>：</p><p>win7及以上64位windows操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：</p><p>①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p>**3、程序如何安装：**不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p><h1 id="程序使用说明-1" tabindex="-1">程序使用说明 <a class="header-anchor" href="#程序使用说明-1" aria-label="Permalink to &quot;程序使用说明&quot;">​</a></h1><p><strong>解压后直接使用即可，不需要安装，程序可以放在任意位置</strong></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2807.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2807.html</a></p>',160)])])}const u=r(s,[["render",e]]);export{c as __pageData,u as default};
